138: /// Keeps track of all voting rounds (block numbers) within a session.
139: /// Only round numbers > `best_done` are of interest, all others are considered stale.
140: ///
141: /// Does not do any validation on votes or signatures, layers above need to handle that (gossip).
142: #[derive(Debug, Decode, Encode, PartialEq)]
143: pub(crate) struct Rounds<B: Block, AuthorityId: AuthorityIdBound> {
144: 	rounds: BTreeMap<Commitment<NumberFor<B>>, RoundTracker<AuthorityId>>,
145: 	previous_votes: BTreeMap<
146: 		(AuthorityId, NumberFor<B>),
147: 		VoteMessage<NumberFor<B>, AuthorityId, <AuthorityId as RuntimeAppPublic>::Signature>,
148: 	>,
149: 	session_start: NumberFor<B>,
150: 	validator_set: WeightedValidatorSet<AuthorityId>,
151: 	mandatory_done: bool,
152: 	best_done: Option<NumberFor<B>>,
153: }
154: 
155: impl<B, AuthorityId> Rounds<B, AuthorityId>
156: where
157: 	B: Block,
158: 	AuthorityId: AuthorityIdBound,
159: {
160: 	pub(crate) fn new(
161: 		session_start: NumberFor<B>,
162: 		validator_set: ValidatorSet<AuthorityId>,
163: 	) -> Self {
164: 		let validator_set = WeightedValidatorSet::new(validator_set);
165: 
166: 		Rounds {
167: 			rounds: BTreeMap::new(),
168: 			previous_votes: BTreeMap::new(),
169: 			session_start,
170: 			validator_set,
171: 			mandatory_done: false,
172: 			best_done: None,
173: 		}
174: 	}
175: 
176: 	pub(crate) fn validator_set(&self) -> &ValidatorSet<AuthorityId> {
177: 		self.validator_set.validator_set()
178: 	}
179: 
180: 	pub(crate) fn validator_set_id(&self) -> ValidatorSetId {
181: 		self.validator_set.id()
182: 	}
183: 
184: 	pub(crate) fn validators(&self) -> &[AuthorityId] {
185: 		self.validator_set.validators()
186: 	}
187: 
188: 	pub(crate) fn session_start(&self) -> NumberFor<B> {
189: 		self.session_start
190: 	}
191: 
192: 	pub(crate) fn mandatory_done(&self) -> bool {
193: 		self.mandatory_done
194: 	}
195: 
196: 	pub(crate) fn add_vote(
197: 		&mut self,
198: 		vote: VoteMessage<NumberFor<B>, AuthorityId, <AuthorityId as RuntimeAppPublic>::Signature>,
199: 	) -> VoteImportResult<B, AuthorityId> {
200: 		let num = vote.commitment.block_number;
201: 		let vote_key = (vote.id.clone(), num);
202: 
203: 		if num < self.session_start || Some(num) <= self.best_done {
204: 			debug!(target: LOG_TARGET, "🥩 received vote for old stale round {:?}, ignoring", num);
205: 			return VoteImportResult::Stale;
206: 		} else if vote.commitment.validator_set_id != self.validator_set_id() {
207: 			debug!(
208: 				target: LOG_TARGET,
209: 				"🥩 expected set_id {:?}, ignoring vote {:?}.",
210: 				self.validator_set_id(),
211: 				vote,
212: 			);
213: 			return VoteImportResult::Invalid;
214: 		} else if !self.validator_set.contains(&vote.id) {
215: 			debug!(
216: 				target: LOG_TARGET,
217: 				"🥩 received vote {:?} from validator that is not in the validator set, ignoring",
218: 				vote
219: 			);
220: 			return VoteImportResult::Invalid;
221: 		}
222: 
223: 		let Some(vote_weight) = self.validator_set.vote_weight(&vote.id) else {
224: 			debug!(
225: 				target: LOG_TARGET,
226: 				"🥩 invalid validator.id (missing vote weight), ignoring vote {:?}",
227: 				vote
228: 			);
229: 			return VoteImportResult::Invalid;
230: 		};
231: 
232: 		if let Some(previous_vote) = self.previous_votes.get(&vote_key) {
233: 			// is the same public key voting for a different payload?
234: 			if previous_vote.commitment.payload != vote.commitment.payload {
235: 				debug!(
236: 					target: LOG_TARGET,
237: 					"🥩 detected equivocated vote: 1st: {:?}, 2nd: {:?}", previous_vote, vote
238: 				);
239: 				return VoteImportResult::DoubleVoting(DoubleVotingProof {
240: 					first: previous_vote.clone(),
241: 					second: vote,
242: 				});
243: 			}
244: 		} else {
245: 			// this is the first vote sent by `id` for `num`, all good
246: 			self.previous_votes.insert(vote_key, vote.clone());
247: 		}
248: 
249: 		// add valid vote
250: 		let round = self.rounds.entry(vote.commitment.clone()).or_default();
251: 		if round.add_vote((vote.id, vote.signature), vote_weight) &&
252: 			round.is_done(threshold(self.validator_set.len()))
253: 		{
254: 			if let Some(round) = self.rounds.remove_entry(&vote.commitment) {
255: 				return VoteImportResult::RoundConcluded(self.signed_commitment(round));
256: 			}
257: 		}
258: 		VoteImportResult::Ok
259: 	}
260:

260: 
261: 	fn signed_commitment(
262: 		&mut self,
263: 		round: (Commitment<NumberFor<B>>, RoundTracker<AuthorityId>),
264: 	) -> SignedCommitment<NumberFor<B>, <AuthorityId as RuntimeAppPublic>::Signature> {
265: 		let votes = round.1.votes;
266: 		let signatures = self
267: 			.validators()
268: 			.iter()
269: 			.map(|authority_id| votes.get(authority_id).cloned())
270: 			.collect();
271: 		SignedCommitment { commitment: round.0, signatures }
272: 	}
273: 
274: 	pub(crate) fn conclude(&mut self, round_num: NumberFor<B>) {
275: 		// Remove this and older (now stale) rounds.
276: 		self.rounds.retain(|commitment, _| commitment.block_number > round_num);
277: 		self.previous_votes.retain(|&(_, number), _| number > round_num);
278: 		self.mandatory_done = self.mandatory_done || round_num == self.session_start;
279: 		self.best_done = self.best_done.max(Some(round_num));
280: 		if round_num == self.session_start {
281: 			info!(target: LOG_TARGET, "🥩 Concluded mandatory round #{}", round_num);
282: 		} else {
283: 			debug!(target: LOG_TARGET, "🥩 Concluded optional round #{}", round_num);
284: 		}
285: 	}
286: }
