102: impl<AuthorityId: AuthorityIdBound> WeightedValidatorSet<AuthorityId> {
103: 	fn new(validator_set: ValidatorSet<AuthorityId>) -> Self {
104: 		let voting_weights =
105: 			validator_set.validators().iter().fold(BTreeMap::new(), |mut acc, authority| {
106: 				*acc.entry(authority.to_owned()).or_insert(0) += 1;
107: 				acc
108: 			});
109: 
110: 		Self { validator_set, voting_weights }
111: 	}
112: 
113: 	fn validator_set(&self) -> &ValidatorSet<AuthorityId> {
114: 		&self.validator_set
115: 	}
116: 
117: 	fn id(&self) -> ValidatorSetId {
118: 		self.validator_set.id()
119: 	}
120: 
121: 	fn validators(&self) -> &[AuthorityId] {
122: 		self.validator_set.validators()
123: 	}
124: 
125: 	fn len(&self) -> usize {
126: 		self.validator_set.len()
127: 	}
128: 
129: 	fn contains(&self, authority_id: &AuthorityId) -> bool {
130: 		self.validators().iter().any(|id| authority_id == id)
131: 	}
132: 
133: 	fn vote_weight(&self, authority_id: &AuthorityId) -> Option<VoteWeight> {
134: 		self.voting_weights.get(authority_id).copied()
135: 	}
136: }
